    "enunciado": "O acompanhamento pré-natal é essencial para a redução da incidência de mortalidade materna, do baixo peso ao nascer e da mortalidade perinatal. A recomendação do Ministério da Saúde acerca do calendário de consultas pré-natais de risco habitual deve ser, no mínimo:",
