    "enunciado": "A diabetes é uma doença crônica que afeta os idosos com grande prevalência. A descompensação aguda grave no diabético com hiperglicemia pode gerar produção de corpos cetônicos (pela queima de gordura corporal), desidratação e alterações em graus variáveis da consciência. Esses sintomas são referentes a:",
