    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Administrativo - Saúde/40h Em um município brasileiro, observa-se um aumento significativo no número de casos de dengue nos últimos meses. A equipe de Vigilância Epidemiológica local investiga a situação e identifica diversos focos do mosquito Aedes aegypti, transmissor da doença. Diante do exposto, a medida mais importante para controlar o surto de dengue no município é:",
