    "resposta_correta": "A",
    "fundamentacao_correta": "A terapêutica medicamentosa segura exige observância estrita dos preceitos de cálculo de dosagem, proporcionalidade, fórmulas de gotejamento horário (gotas/min = Volume / (Tempo x 3); microgotas/min = Volume / Tempo) e protocolos de farmacovigilância. A alternativa [A] ('medicamento - medicamento; medicamento - alimento; medicamento - bebida alcoólica; medicamento - exames laboratoriais') apresenta a resposta matemática e clínica correta.",
