    "enunciado": "O Ministério da Saúde estabelece o número mínimo e a distribuição temporal das consultas de pré-natal para garantir detecção precoce de agravos, abordagem de fatores de risco e vigilância fetal adequada na gestação. De acordo com essas recomendações, o mínimo obrigatório de consultas e sua distribuição são:",
