    "fundamentacao_correta": "Segundo as Diretrizes Nacionais de Assistência ao Pré-Natal de Baixo Risco e Atenção ao Parto e Puerpério (Ministério da Saúde), a assistência obstétrica de enfermagem visa à humanização do cuidado, vigilância materno-fetal qualificada e identificação precoce de intercorrências. A alternativa [A] ('duas consultas no 1º trimestre, duas no 2º trimestre e três no 3º trimestre, totalizando sete') descreve a conduta clínica e preventiva preconizada.",
