    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Preto - SP - Analista em Vigilância Sanitária - Enfermeiro Uma mulher procura um serviço de saúde, informando que vai viajar com o filho de 6 meses para um município paulista que se encontra em situação de surto ativo de sarampo. Nessa situação, o profissional de saúde deve orientar que",
