    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Preto - SP - Analista em Vigilância Sanitária - Enfermeiro Para atuar na Central de Materiais e Esterilização, o enfermeiro deve estar atento aos requisitos de boas práticas para o processamento de produtos para saúde. Um desses requisitos recomendados pela Agência Nacional de Vigilância Sanitária é que",
    "alternativas": [
      {
        "id": "A",
        "texto": "os produtos para saúde passíveis de processamento, de acordo com a sua classificação de risco, inclusive os consignados, devem ser submetidos ao processo de limpeza, dentro da própria CME do serviço de saúde ou na empresa processadora, antes de sua desinfecção ou esterilização, excluídos os de propriedade do cirurgião."
      },
      {
        "id": "B",
        "texto": "a limpeza dos produtos para saúde, seja manual ou automatizada, deve ser avaliada por meio da inspeção visual, com o auxílio de lentes intensificadoras de imagem, de no mínimo oito vezes de aumento, complementada, quando indicado, por testes químicos disponíveis no mercado."
      },
      {
        "id": "C",
        "texto": "é permitido o uso de autoclave gravitacional de capacidade superior a 100 litros, desde que sejam dos modelos chamados \"de barreira\", que possuem portas duplas que impedem contaminação da área limpa, com entrada do material contaminado."
      },
      {
        "id": "D",
        "texto": "a água utilizada no processo de geração do vapor das autoclaves deve atender às especificações dos profissionais da Comissão de Controle de Infecção Hospitalar e da Comissão de Segurança do Paciente."
      },
      {
        "id": "E",
        "texto": "na limpeza manual dos produtos de saúde, a fricção deve ser realizada, preferencialmente, com acessórios abrasivos e que liberem partículas de, no máximo, cinco micra."
      }
    ],
    "resposta_correta": "B",
    "fundamentacao_correta": "Com base na literatura de propedêutica e fundamentos de enfermagem (Brunner & Suddarth; Potter & Perry) e normas técnicas do Ministério da Saúde, a atuação segura e eficiente da enfermagem exige domínio dos procedimentos assistenciais e fundamentação científica em cada etapa do atendimento. A alternativa [B] ('a limpeza dos produtos para saúde, seja manual ou automatizada, deve ser avaliada por meio da inspeção visual, com o auxílio de lentes intensificadoras de imagem, de no mínimo oito vezes de aumento, complementada, quando indicado, por testes químicos disponíveis no mercado.') configura a resposta correta e plenamente fundamentada.",
