    "enunciado": "Preto - SP - Analista em Vigilância Sanitária - Enfermeiro Uma pluralidade de ciências participa das ações da área de Vigilância Sanitária, dentre elas, está a ciência jurídica. Para este campo da ciência, efetividade significa",
