        "texto": "a capacidade de a norma ser atendida tanto pelos destinatários quanto pelos aplicadores do direito. É indispensável, então, o cumprimento, por parte dos indivíduos, daquilo que está prescrito no ordenamento, para que se alcance a efetividade."
