    "enunciado": "Na Enfermagem, a Prática Baseada em Evidência envolve a definição de um problema, a averiguação e avaliação crítica das evidências disponíveis, a implementação destas na prática e apreciação dos resultados. De acordo com o Conselho Federal de Enfermagem, a Prática Baseada em Evidência ocorre por meio da integração dos seguintes elementos:",
