    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Federal - Consultor Técnico-Legislativo - Enfermeiro Em um estudo realizado em um município brasileiro, foi medida a taxa de incidência de acidente vascular cerebral em 118.539 mulheres com idade entre 30-55 anos que, em 2001, não tinham histórico de doença coronariana, acidente vascular cerebral ou câncer. Um total de 274 casos de acidente vascular cerebral foi observado ao longo de oito anos de acompanhamento (908.447 pessoas/ano). A taxa de densidade de incidência de acidente vascular cerebral para toda a população foi de 30,2 por 100 mil pessoas/ano de observação. Nessa situação, a Taxa de incidência cumulativa ou risco para acidente vascular cerebral, no período de oito anos, por mil habitantes, corresponde à",
