    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Federal - Consultor Técnico-Legislativo - Enfermeiro Um homem de 48 anos apresenta comprometimento pulmonar, lesões ulceradas de pele e linfoadenopatia. O diagnóstico é paracoccidioidomicose, que é uma doença: I. transmitida pela inalação do fungo P. brasiliensis. II. com período de incubação que pode variar de 1 mês a anos. III. de notificação compulsória nacional. IV. viral transmitida por secreções respiratórias. Está correto o que se afirma APENAS em",
