    "enunciado": "Um enfermeiro é convidado a participar da equipe que irá avaliar um projeto físico de um estabelecimento assistencial de saúde. Considerando a Resolução da Diretoria Colegiada 50 (RDC) da Agencia Nacional de Vigilância Sanitária 2002 (ANVISA), o enfermeiro deve saber que",
