    "resposta_correta": "E",
    "fundamentacao_correta": "Com base na literatura de propedêutica e fundamentos de enfermagem (Brunner & Suddarth; Potter & Perry) e normas técnicas do Ministério da Saúde, a atuação segura e eficiente da enfermagem exige domínio dos procedimentos assistenciais e fundamentação científica em cada etapa do atendimento. A alternativa [E] ('os tetos em áreas críticas devem ser contínuos, sendo proibido o uso de forros falsos removíveis, do tipo que interfira na assepsia dos ambientes.') configura a resposta correta e plenamente fundamentada.",
