    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Federal - Consultor Legislativo - Saúde Um sangue foi coletado e transportado ao laboratório de processamento de hemocomponentes e, em seguida, armazenado para liberação para estoque, distribuição e dispensação ao usuário, conforme solicitação médica. No entanto, reação transfusional, notificada no Sistema de Notificação em Vigilância Sanitária − Notivisa, foi associada a esse sangue e hemocomponentes. A investigação pós-notificação permitiu concluir que os efeitos adversos foram decorrentes de vários problemas constatados na cadeia de frio (ou cadeia do frio). Nesse contexto,",
    "alternativas": [
      {
        "id": "A",
        "texto": "os problemas da cadeia de frio foram por defeito na máquina de aférese, equipamento que garante baixas temperaturas do sangue e hemoderivados durante a transfusão sanguínea."
      },
      {
        "id": "B",
        "texto": "a notificação deveria ter sido feita apenas no Sistema Nacional de Hemovigilância (SNH) por se tratar do ciclo produtivo do sangue de modo a registrar, de imediato, os problemas na cadeia de frio."
      },
      {
        "id": "C",
        "texto": "a cadeia de frio deveria garantir o congelamento do sangue e todos os seus hemocomponentes até a dispensação ao usuário."
      },
      {
        "id": "D",
        "texto": "se o sangue originou hemoderivados, estes não sofreram alteração e perda de qualidade pois não necessitam da cadeia de frio."
      },
      {
        "id": "E",
        "texto": "houve uma ação de hemovigilância, a qual faz parte do ciclo do sangue, e a notificação dos efeitos adversos foi executada no sistema de informação adequado (Notivisa)."
      }
    ],
    "resposta_correta": "E",
    "fundamentacao_correta": "Com base na literatura de propedêutica e fundamentos de enfermagem (Brunner & Suddarth; Potter & Perry) e normas técnicas do Ministério da Saúde, a atuação segura e eficiente da enfermagem exige domínio dos procedimentos assistenciais e fundamentação científica em cada etapa do atendimento. A alternativa [E] ('houve uma ação de hemovigilância, a qual faz parte do ciclo do sangue, e a notificação dos efeitos adversos foi executada no sistema de informação adequado (Notivisa).') configura a resposta correta e plenamente fundamentada.",
