    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Federal - Consultor Legislativo - Saúde Em relação aos dados de morbidade e mortalidade do Distrito Federal publicados pela Secretaria da Saúde, Diretoria de Vigilância Epidemiológica, no Boletim Epidemiológico (março 2018), é correto afirmar:",
    "alternativas": [
      {
        "id": "A",
        "texto": "Houve redução, de 2004 a 2014, no número de óbitos por Doenças do Aparelho Circulatório."
      },
      {
        "id": "B",
        "texto": "Do total de óbitos, em 2014, a principal causa foi câncer (27,1%), doença para a qual se observou aumento de mortalidade, no período de 2004 a 2014."
      },
      {
        "id": "C",
        "texto": "Dentre as doenças imunopreveníveis, de transmissão respiratória, hepatite A, hídricas e alimentares e dos acidentes com animais peçonhentos, a Doença Diarreica Aguda foi a que teve maior número de casos notificados em seres humanos, em 2017."
      },
      {
        "id": "D",
        "texto": "Foi observado que, dentre os grupos de causas de morte por Doencas Crônicas não Transmissíveis, o segundo lugar ficou com Doenças do Aparelho Respiratório que aumentaram entre 2004 e 2014."
      },
      {
        "id": "E",
        "texto": "Os casos notificados de Doença Sexualmente Transmissível (ou Infecção Sexualmente Transmissível), com predomínio de síndrome do corrimento uretral em homens, suplantaram os casos de dengue, em 2016."
      }
    ],
    "resposta_correta": "C",
    "fundamentacao_correta": "Com base na literatura de propedêutica e fundamentos de enfermagem (Brunner & Suddarth; Potter & Perry) e normas técnicas do Ministério da Saúde, a atuação segura e eficiente da enfermagem exige domínio dos procedimentos assistenciais e fundamentação científica em cada etapa do atendimento. A alternativa [C] ('Dentre as doenças imunopreveníveis, de transmissão respiratória, hepatite A, hídricas e alimentares e dos acidentes com animais peçonhentos, a Doença Diarreica Aguda foi a que teve maior número de casos notificados em seres humanos, em 2017.') configura a resposta correta e plenamente fundamentada.",
