    "cargo": "Técnico de Enfermagem",
    "materia": "Enfermagem",
    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "No âmbito da Notificação Compulsória de doença, agravos e eventos de saúde pública, a epizootia por febre amarela, representa",
    "alternativas": [
      {
        "id": "A",
        "texto": "o aumento expressivo no número do mosquito transmissor da doença."
      },
      {
        "id": "B",
        "texto": "o aumento no número de casos suspeitos da doença em roedores silvestres."
      },
      {
        "id": "C",
        "texto": "o aumento no número de casos urbanos da doença em primatas e humanos."
      },
      {
        "id": "D",
        "texto": "a morte ou adoecimento de cães e gatos com sintomatologia neurológica."
      },
      {
        "id": "E",
        "texto": "a morte de primatas não humanos."
      }
    ],
    "resposta_correta": "E",
    "fundamentacao_correta": "Com base na Constituição Federal de 1988 (Artigos 196 a 200) e nas Leis Orgânicas da Saúde nº 8.080/1990 e 8.142/1990, o SUS rege-se pelos princípios doutrinários de Universalidade, Integralidade e Equidade, somados às diretrizes organizativas de Descentralização, Regionalização e Participação da Comunidade. A alternativa [E] ('a morte de primatas não humanos.') fundamenta-se nos preceitos constitucionais e infraconstitucionais vigentes.",
    "analise_distratores": [
      {
        "letra": "A",
        "motivo": "Incorreta perante os protocolos oficiais do Ministério da Saúde e da banca: 'o aumento expressivo no número do mosquito transmissor da doença....' não corresponde à diretriz ou definição válida."
      },
      {
        "letra": "B",
        "motivo": "Incorreta perante os protocolos oficiais do Ministério da Saúde e da banca: 'o aumento no número de casos suspeitos da doença em roedores silvestres....' não corresponde à diretriz ou definição válida."
      },
      {
        "letra": "C",
        "motivo": "Incorreta perante os protocolos oficiais do Ministério da Saúde e da banca: 'o aumento no número de casos urbanos da doença em primatas e humanos....' não corresponde à diretriz ou definição válida."
      },
      {
        "letra": "D",
        "motivo": "Incorreta perante os protocolos oficiais do Ministério da Saúde e da banca: 'a morte ou adoecimento de cães e gatos com sintomatologia neurológica....' não corresponde à diretriz ou definição válida."
      }
    ],
    "comentario": "Com base na Constituição Federal de 1988 (Artigos 196 a 200) e nas Leis Orgânicas da Saúde nº 8.080/1990 e 8.142/1990, o SUS rege-se pelos princípios doutrinários de Universalidade, Integralidade e Equidade, somados às diretrizes organizativas de Descentralização, Regionalização e Participação da Comunidade. A alternativa [E] ('a morte de primatas não humanos.') fundamenta-se nos preceitos constitucionais e infraconstitucionais vigentes.",
