    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "Dentre as práticas de prevenção de infecção primária de corrente sanguínea causada pela inserção e/ou manuseio de cateter venoso periférico, a Agência Nacional de Vigilância Sanitária recomenda que",
    "alternativas": [
      {
        "id": "A",
        "texto": "durante a inserção e o manuseio do cateter, como rotina, devem ser utilizadas luvas estéreis."
      },
      {
        "id": "B",
        "texto": "se deve usar, preferencialmente, a preparação alcoólica para as mãos, quando estiverem visivelmente sujas, em substituição à lavagem das mãos."
      },
      {
        "id": "C",
        "texto": "as veias de membros inferiores em adultos devem ser utilizadas rotineiramente, devido ao menor risco de embolias e tromboflebites."
      },
      {
        "id": "D",
        "texto": "a cobertura do sítio do local da punção deve ser trocada imediatamente, se houver suspeita de contaminação, e sempre quando úmida, solta, suja ou com a integridade comprometida."
      },
      {
        "id": "E",
        "texto": "deve ser realizada rotineiramente a irrigação contínua do cateter com solução antimicrobiana."
      }
    ],
    "resposta_correta": "D",
    "fundamentacao_correta": "Com base na literatura de propedêutica e fundamentos de enfermagem (Brunner & Suddarth; Potter & Perry) e normas técnicas do Ministério da Saúde, a atuação segura e eficiente da enfermagem exige domínio dos procedimentos assistenciais e fundamentação científica em cada etapa do atendimento. A alternativa [D] ('a cobertura do sítio do local da punção deve ser trocada imediatamente, se houver suspeita de contaminação, e sempre quando úmida, solta, suja ou com a integridade comprometida.') configura a resposta correta e plenamente fundamentada.",
