    "assunto": "Epidemiologia e Vigilância em Saúde",
    "enunciado": "De acordo com a Agência Nacional de Vigilância Sanitária − ANVISA, no processamento de produtos para a saúde por meio da esterilização utilizando-se o vapor saturado sobre pressão, autoclave, o enfermeiro deve considerar que",
